export function joinUrl(base: string, ...parts: string[]): string {
  const all = [base, ...parts].filter(Boolean);
  if (all.length === 0) return "";

  let out = all[0]!;
  for (const p of all.slice(1)) {
    if (!out.endsWith("/")) out += "/";
    out += p.startsWith("/") ? p.slice(1) : p;
  }

  return out.replace(/(?<!:)\/{2,}/g, "/");
}

