export type JsonStorage = {
  get<T>(key: string): T | null;
  set<T>(key: string, value: T): void;
  remove(key: string): void;
};

function getStorage(storage: "localStorage" | "sessionStorage"): Storage | null {
  try {
    const s = globalThis[storage] as Storage | undefined;
    if (!s) return null;
    const testKey = "__yutils_test__";
    s.setItem(testKey, "1");
    s.removeItem(testKey);
    return s;
  } catch {
    return null;
  }
}

export function createJsonStorage(storage: "localStorage" | "sessionStorage" = "localStorage"): JsonStorage {
  const s = getStorage(storage);

  return {
    get<T>(key: string) {
      if (!s) return null;
      const raw = s.getItem(key);
      if (raw == null) return null;
      try {
        return JSON.parse(raw) as T;
      } catch {
        return null;
      }
    },
    set<T>(key: string, value: T) {
      if (!s) return;
      s.setItem(key, JSON.stringify(value));
    },
    remove(key: string) {
      if (!s) return;
      s.removeItem(key);
    }
  };
}

