export type Throttled<TArgs extends unknown[]> = ((...args: TArgs) => void) & {
  cancel: () => void;
};

export function throttle<TArgs extends unknown[]>(
  fn: (...args: TArgs) => void,
  intervalMs: number
): Throttled<TArgs> {
  let last = 0;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let pendingArgs: TArgs | undefined;

  const throttled = ((...args: TArgs) => {
    const now = Date.now();
    const remaining = intervalMs - (now - last);

    pendingArgs = args;

    if (remaining <= 0) {
      if (timer) clearTimeout(timer);
      timer = undefined;
      last = now;
      const a = pendingArgs;
      pendingArgs = undefined;
      if (a) fn(...a);
      return;
    }

    if (timer) return;
    timer = setTimeout(() => {
      timer = undefined;
      last = Date.now();
      const a = pendingArgs;
      pendingArgs = undefined;
      if (a) fn(...a);
    }, remaining);
  }) as Throttled<TArgs>;

  throttled.cancel = () => {
    if (timer) clearTimeout(timer);
    timer = undefined;
    pendingArgs = undefined;
  };

  return throttled;
}

