export type FormatBytesOptions = {
  decimals?: number;
  base?: 1000 | 1024;
};
/**
 * 给数据添加内存单位
 * @param {number} bytes -要转换的数据
 * @param {FormatBytesOptions} opts - {
 *    decimals?: number --保留小数点几位
 *    base?: 1000 | 1024 --数值
 * }
 * @return {string} 1MB
 * */
export function formatBytes(bytes: number, opts: FormatBytesOptions = {}): string {
  const { decimals = 1, base = 1024 } = opts;
  if (!Number.isFinite(bytes)) return "NaN";
  if (bytes === 0) return "0 B";

  const neg = bytes < 0;
  const b = Math.abs(bytes);
  const units = base === 1000 ? ["B", "kB", "MB", "GB", "TB", "PB"] : ["B", "KiB", "MiB", "GiB", "TiB", "PiB"];
  const i = Math.min(units.length - 1, Math.floor(Math.log(b) / Math.log(base)));
  const v = b / Math.pow(base, i);
  const s = v.toFixed(Math.max(0, decimals));
  return `${neg ? "-" : ""}${s} ${units[i]}`;
}

